import{_ as e,o as a,c as o,a7 as n}from"./chunks/framework.C4ZIv4ii.js";const m=JSON.parse('{"title":"Animations","description":"","frontmatter":{},"headers":[],"relativePath":"slider/animations.md","filePath":"slider/animations.md","lastUpdated":1785395078000}'),r={name:"slider/animations.md"};function i(d,t,s,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="animations" tabindex="-1">Animations <a class="header-anchor" href="#animations" aria-label="Permalink to &quot;Animations&quot;">​</a></h1><p>Animation is the heart of Falcon Slider. Every layer can animate <strong>in</strong> (entrance), animate <strong>out</strong> (exit), <strong>reveal</strong> its text character by character, and <strong>loop</strong> gently while it rests. All of it plays on a timeline you control, live on the canvas and identically on the frontend.</p><div class="tip custom-block"><p class="custom-block-title">Editor and frontend always match</p><p>Whatever you set — animation, reveal, duration, delay, idle loop — plays the same on the editor canvas <strong>and</strong> the live frontend, by default. No toggle needed.</p></div><hr><h2 id="entrance-exit-animations" tabindex="-1">Entrance &amp; exit animations <a class="header-anchor" href="#entrance-exit-animations" aria-label="Permalink to &quot;Entrance &amp; exit animations&quot;">​</a></h2><p>In the <strong>Layers</strong> tab, each layer has an <strong>In</strong> (entrance) and <strong>Out</strong> (exit) animation. Pick a <strong>preset</strong>:</p><table tabindex="0"><thead><tr><th>Preset</th><th>Motion</th></tr></thead><tbody><tr><td><code>none</code></td><td>No motion (appears instantly)</td></tr><tr><td><code>fade</code></td><td>Fade in</td></tr><tr><td><code>from-bottom</code> / <code>from-top</code></td><td>Slide up / down into place</td></tr><tr><td><code>from-left</code> / <code>from-right</code></td><td>Slide in horizontally</td></tr><tr><td><code>from-bottom-left</code> / <code>from-top-right</code></td><td>Slide in diagonally</td></tr><tr><td><code>zoom-in</code> / <code>zoom-out</code></td><td>Scale up / down into place</td></tr><tr><td><code>zoom-blur</code></td><td>Scale in with a blur</td></tr><tr><td><code>blur-in</code></td><td>Sharpen from blur</td></tr><tr><td><code>rotate-in</code></td><td>Rotate into place</td></tr><tr><td><code>flip-x</code> / <code>flip-y</code></td><td>3D flip on the X / Y axis</td></tr><tr><td><code>skew-in</code></td><td>Skew into place</td></tr></tbody></table><h3 id="timing" tabindex="-1">Timing <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;Timing&quot;">​</a></h3><p>Each animation has three timing controls:</p><ul><li><strong>Delay</strong> — how long to wait (ms) after the slide shows before this layer animates. Stagger layers by giving each a larger delay.</li><li><strong>Duration</strong> — how long the animation runs (ms).</li><li><strong>Easing</strong> — the acceleration curve: <code>ease</code>, <code>ease-out</code>, <code>ease-in</code>, <code>ease-in-out</code>, or a springy <code>cubic-bezier(.34,1.56,.64,1)</code> overshoot.</li></ul><p>Click the ▶ <strong>replay</strong> icon next to any animation to preview it on the canvas.</p><hr><h2 id="text-reveal" tabindex="-1">Text reveal <a class="header-anchor" href="#text-reveal" aria-label="Permalink to &quot;Text reveal&quot;">​</a></h2><p>Text layers can <strong>reveal</strong> their content instead of a plain entrance. In the Layers tab set <strong>Reveal</strong> to:</p><table tabindex="0"><thead><tr><th>Reveal</th><th>Effect</th></tr></thead><tbody><tr><td><code>none</code></td><td>Normal (uses the entrance preset)</td></tr><tr><td><code>typewriter</code></td><td>Types the text out character by character with a blinking cursor</td></tr><tr><td><code>chars</code></td><td>Each <strong>character</strong> fades/rises in, one after another</td></tr><tr><td><code>words</code></td><td>Each <strong>word</strong> fades/rises in, one after another</td></tr></tbody></table><p>Reveals honour the layer&#39;s <strong>delay</strong> — the reveal waits for the delay, then plays. Combine a reveal with a delay to sequence headlines dramatically.</p><hr><h2 id="idle-loops" tabindex="-1">Idle loops <a class="header-anchor" href="#idle-loops" aria-label="Permalink to &quot;Idle loops&quot;">​</a></h2><p>An <strong>idle loop</strong> keeps a layer gently in motion <em>after</em> it has entered — great for drawing the eye to a badge or button. Choose a <strong>loop</strong>:</p><table tabindex="0"><thead><tr><th>Loop</th><th>Motion</th></tr></thead><tbody><tr><td><code>none</code></td><td>Static once entered</td></tr><tr><td><code>float</code></td><td>Slow up-and-down drift</td></tr><tr><td><code>bob</code></td><td>Gentle bounce</td></tr><tr><td><code>pulse</code></td><td>Soft scale pulsing</td></tr><tr><td><code>sway</code></td><td>Side-to-side sway</td></tr><tr><td><code>spin</code></td><td>Continuous rotation</td></tr></tbody></table><p>Loops run continuously and combine with parallax and hover effects.</p><hr><h2 id="building-an-animated-sequence" tabindex="-1">Building an animated sequence <a class="header-anchor" href="#building-an-animated-sequence" aria-label="Permalink to &quot;Building an animated sequence&quot;">​</a></h2><p>A typical hero headline sequence:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0 ms     Background fades in, Ken Burns begins</span></span>
<span class="line"><span>200 ms   Eyebrow text  → from-left,  reveal: words</span></span>
<span class="line"><span>600 ms   Headline      → from-bottom, reveal: chars</span></span>
<span class="line"><span>1200 ms  Sub-headline  → fade</span></span>
<span class="line"><span>1600 ms  CTA button    → zoom-in,   idle loop: pulse</span></span></code></pre></div><p>Set each layer&#39;s <strong>delay</strong> to the times above, pick the presets, and press <strong>Preview</strong> to watch the whole slide play with autoplay and every animation — exactly as visitors will see it.</p><hr><h2 id="accessibility-reduced-motion" tabindex="-1">Accessibility (reduced motion) <a class="header-anchor" href="#accessibility-reduced-motion" aria-label="Permalink to &quot;Accessibility (reduced motion)&quot;">​</a></h2><p>By default, animations always play. If you&#39;d rather respect a visitor&#39;s operating-system <strong>&quot;reduce motion&quot;</strong> setting for accessibility, enable <strong>Respect reduced-motion</strong> in the slider <strong>Settings</strong> tab. When on, visitors who ask their OS to reduce motion get a gentle fade instead of movement, idle loops are paused, and Ken Burns / parallax are disabled — while everyone else sees the full animation.</p><hr><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/falconcms/slider/navigation.html">Navigation &amp; Managing</a> — autoplay, arrows, thumbnails, revisions and full-screen preview</li><li><a href="/falconcms/slider/layers.html">Layers</a> — the layers you&#39;re animating</li></ul>`,32)])])}const g=e(r,[["render",i]]);export{m as __pageData,g as default};
